namespace RonSijm.FluidHumidifier.Factories.Connect;

public class UserFactory(string resourceName = null, Action<Humidifier.Connect.User> factoryAction = null) : ResourceFactory<Humidifier.Connect.User>(resourceName)
{

    internal List<InnerUserAfterContactWorkConfigPerChannelFactory> AfterContactWorkConfigsFactories { get; set; } = [];

    internal List<InnerUserPersistentConnectionConfigFactory> PersistentConnectionConfigsFactories { get; set; } = [];

    internal List<InnerUserUserProficiencyFactory> UserProficienciesFactories { get; set; } = [];

    internal List<InnerUserVoiceEnhancementConfigFactory> VoiceEnhancementConfigsFactories { get; set; } = [];

    internal List<InnerUserPhoneNumberConfigFactory> PhoneNumberConfigsFactories { get; set; } = [];

    internal List<InnerUserAutoAcceptConfigFactory> AutoAcceptConfigsFactories { get; set; } = [];

    internal InnerUserUserPhoneConfigFactory PhoneConfigFactory { get; set; }

    internal InnerUserUserIdentityInfoFactory IdentityInfoFactory { get; set; }

    protected override Humidifier.Connect.User Create()
    {
        var userResult = CreateUser();
        factoryAction?.Invoke(userResult);

        return userResult;
    }

    private Humidifier.Connect.User CreateUser()
    {
        var userResult = new Humidifier.Connect.User
        {
            GivenName = InputResourceName,
        };

        return userResult;
    }
    public override void CreateChildren(Humidifier.Connect.User result)
    {
        base.CreateChildren(result);

        result.AfterContactWorkConfigs = AfterContactWorkConfigsFactories.Any() ? AfterContactWorkConfigsFactories.Select(x => x.Build()).ToList() : null;
        result.PersistentConnectionConfigs = PersistentConnectionConfigsFactories.Any() ? PersistentConnectionConfigsFactories.Select(x => x.Build()).ToList() : null;
        result.UserProficiencies = UserProficienciesFactories.Any() ? UserProficienciesFactories.Select(x => x.Build()).ToList() : null;
        result.VoiceEnhancementConfigs = VoiceEnhancementConfigsFactories.Any() ? VoiceEnhancementConfigsFactories.Select(x => x.Build()).ToList() : null;
        result.PhoneNumberConfigs = PhoneNumberConfigsFactories.Any() ? PhoneNumberConfigsFactories.Select(x => x.Build()).ToList() : null;
        result.AutoAcceptConfigs = AutoAcceptConfigsFactories.Any() ? AutoAcceptConfigsFactories.Select(x => x.Build()).ToList() : null;
        result.PhoneConfig ??= PhoneConfigFactory?.Build();
        result.IdentityInfo ??= IdentityInfoFactory?.Build();
    }

} // End Of Class

